package com.example.starter.robot;

import org.springframework.boot.context.properties.ConfigurationProperties;

import java.nio.file.Path;

/**
 * 机器人模型编译服务配置。
 *
 * @param workspaceRoot 受控工作目录根路径，入口 Xacro 及其全部传递依赖必须位于该目录内
 */
@ConfigurationProperties(prefix = "robot.compiler")
public record RobotCompilerProperties(Path workspaceRoot) {

    public RobotCompilerProperties {
        if (workspaceRoot == null) {
            workspaceRoot = Path.of("robot-workspace");
        }
    }
}

package com.example.starter.robot;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

import java.util.Map;

/**
 * 编译请求。
 *
 * @param entry      受控工作目录内的入口 Xacro 相对路径
 * @param parameters Xacro 参数覆盖，键为参数名，值为字符串形式的参数值；请求参数优先于文件默认值
 * @param requestId  请求标识，用于响应与错误体回溯
 */
public record CompileRequest(
        @NotBlank String entry,
        @NotNull Map<String, String> parameters,
        @NotBlank String requestId) {
}

package com.example.starter.robot;

import java.util.List;

/**
 * 单个依赖文件的内容摘要。
 *
 * @param path     相对于受控工作目录的 POSIX 风格路径
 * @param sha256   依赖文件原始字节的 SHA-256（十六进制小写）
 * @param entry    是否为入口文件
 */
public record DependencyInfo(String path, String sha256, boolean entry) {
}

package com.example.starter.robot;

import org.springframework.http.HttpStatus;

/**
 * 编译服务业务错误码及对应的 HTTP 状态。
 */
public enum ErrorCode {

    /** 请求体或字段校验失败。 */
    INVALID_REQUEST(HttpStatus.BAD_REQUEST),
    /** 入口文件不存在或不是普通文件。 */
    ENTRY_NOT_FOUND(HttpStatus.BAD_REQUEST),
    /** include 引用的文件不存在。 */
    INCLUDE_NOT_FOUND(HttpStatus.BAD_REQUEST),
    /** include 路径解析后越出受控工作目录。 */
    INCLUDE_OUT_OF_BOUNDS(HttpStatus.BAD_REQUEST),
    /** ${name} 引用了未定义的参数。 */
    UNDEFINED_PARAMETER(HttpStatus.BAD_REQUEST),
    /** 展开后的 URDF 不满足结构、名称、引用、数值等约束。 */
    INVALID_URDF(HttpStatus.BAD_REQUEST),
    /** 使用了受限子集之外的 Xacro 构造。 */
    UNSUPPORTED_XACRO(HttpStatus.UNPROCESSABLE_ENTITY),
    /** include 形成循环引用。 */
    INCLUDE_CYCLE(HttpStatus.UNPROCESSABLE_ENTITY),
    /** 服务端未预期错误。 */
    INTERNAL_ERROR(HttpStatus.INTERNAL_SERVER_ERROR);

    private final HttpStatus status;

    ErrorCode(HttpStatus status) {
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }
}

package com.example.starter.robot;

import java.util.List;

/**
 * 编译流程业务异常。
 */
public class CompileException extends RuntimeException {

    private final ErrorCode errorCode;
    private final transient List<String> chain;

    public CompileException(ErrorCode errorCode, String message) {
        this(errorCode, message, List.of());
    }

    public CompileException(ErrorCode errorCode, String message, List<String> chain) {
        super(message);
        this.errorCode = errorCode;
        this.chain = List.copyOf(chain);
    }

    public ErrorCode errorCode() {
        return errorCode;
    }

    public List<String> chain() {
        return chain;
    }
}

package com.example.starter.robot;

import java.util.List;

/**
 * 统一错误响应体。
 *
 * @param requestId 触发错误的请求标识，无法解析时为 null
 * @param code      业务错误码
 * @param message   错误说明
 * @param chain     循环引用时从入口到重复文件的完整链路，其余场景为空
 */
public record ErrorResponse(String requestId, String code, String message, List<String> chain) {
}

