/** 替换文本中的全部 ${name}；未定义参数返回 400，非法表达式返回 UNSUPPORTED_XACRO。 */
private String substituteText(String text, Context ctx, String fileRel) {
    if (text.indexOf("${") < 0) {
        return text;
    }
    java.util.regex.Matcher matcher = PARAMETER_TOKEN.matcher(text);
    StringBuilder result = new StringBuilder();
    while (matcher.find()) {
        String expression = matcher.group(1).trim();
        if (expression.contains("${") || !PARAMETER_NAME.matcher(expression).matches()) {
            throw unsupported("仅支持 ${参数名} 替换，不支持表达式: ${" + matcher.group(1) + "}", fileRel);
        }
        String value = ctx.parameters.get(expression);
        if (value == null) {
            throw new CompileException(ErrorCode.UNDEFINED_PARAMETER,
                    "未定义的参数: " + expression + "（文件 " + fileRel + "）");
        }
        matcher.appendReplacement(result, java.util.regex.Matcher.quoteReplacement(value));
