                if (cached != null) {
                    return new CompileResponse(request.requestId(), request.entry(),
                            cached.urdf(), cached.urdfSha256(), cacheKey, true,
                            cached.dependencies(), cached.expansionChain());
                }

                // 校验失败在此抛出，不会到达缓存写入
