                </robot>
                """);
        assertThatThrownBy(() -> expander.expand(workspace, "expr.xacro", Map.of()))
                .isInstanceOf(CompileException.class)
                .satisfies(ex -> assertThat(((CompileException) ex).errorCode())
                        .isEqualTo(ErrorCode.UNSUPPORTED_XACRO));
