package com.example.starter.robot;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

/**
 * 临时：打印交付示例的稳定缓存键与 URDF 哈希，随后固化为常量断言。
 */
class PinnedHashProbeTest {

    @TempDir
    Path workspace;

    @Test
    void printPinnedHashes() throws IOException {
        Files.createDirectories(workspace.resolve("includes"));
        Files.createDirectories(workspace.resolve("robots"));
        Files.writeString(workspace.resolve("includes/base.urdf.xacro"), """
                <?xml version="1.0"?>
                <robot name="parts" xmlns:xacro="http://www.ros.org/wiki/xacro">
                  <xacro:property name="base_radius" value="0.1"/>
                  <link name="base_link">
                    <inertial>
                      <mass value="1.0"/>
                      <inertia ixx="0.01" ixy="0" ixz="0" iyy="0.01" iyz="0" izz="0.01"/>
                    </inertial>
                    <visual>
                      <geometry><sphere radius="${base_radius}"/></geometry>
                    </visual>
                  </link>
                </robot>
                """, StandardCharsets.UTF_8);
        Files.writeString(workspace.resolve("robots/main.urdf.xacro"), """
                <?xml version="1.0"?>
                <robot name="demo" xmlns:xacro="http://www.ros.org/wiki/xacro">
                  <xacro:include filename="../includes/base.urdf.xacro"/>
                  <xacro:property name="arm_length" value="0.5"/>
                  <link name="arm_link">
                    <visual>
                      <origin xyz="0 0 0.25" rpy="0 0 0"/>
                      <geometry><cylinder radius="0.05" length="${arm_length}"/></geometry>
                    </visual>
                  </link>
                  <joint name="base_to_arm" type="fixed">
                    <parent link="base_link"/>
                    <child link="arm_link"/>
                  </joint>
                </robot>
                """, StandardCharsets.UTF_8);

        XacroExpander expander = new XacroExpander();
        ExpansionResult result = expander.expand(workspace, "robots/main.urdf.xacro",
                Map.of("arm_length", "0.8"));
        String urdfHash = Digests.sha256Hex(result.urdf());
        CompileService service = new CompileService(expander, new UrdfValidator(), null,
                new RobotCompilerProperties(workspace));
        String cacheKey = service.buildCacheKey("robots/main.urdf.xacro",
                result.dependencies(), result.parameters());
        System.out.println("PINNED_URDF_SHA256=" + urdfHash);
        System.out.println("PINNED_CACHE_KEY=" + cacheKey);
        System.out.println("PINNED_URDF_BEGIN");
        System.out.print(result.urdf());
        System.out.println("PINNED_URDF_END");
    }
}

