46	    /** 参数名语法：字母/下划线开头，后接字母、数字、下划线。 */
47	    private static final Pattern PARAMETER_NAME = Pattern.compile("[A-Za-z_][A-Za-z0-9_]*");
48	    private static final Pattern PARAMETER_TOKEN = Pattern.compile("\\$\\{([^}]*)}");
