53	        try {
54	            DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
55	            factory.setNamespaceAware(true);
56	            factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
57	            factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
58	            factory.setExpandEntityReferences(false);
